\version "2.27.2"
% automatically converted by musicxml2ly from 43i-MultiStaff-StaffChange-SingleVoice.xml
\pointAndClickOff

\header {
  texidoc = "Staff changes in a piano staff.

    There is a single voice starting in staff 2 that spreads its notes over the
    two staves; there is no separate voice in staff 1."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOneS = \relative c' {
  \clef "treble" \time 4/4 \key c \major s1 }

PartPOneVoiceTwo = \relative a {
  \clef "bass" \time 4/4 \key c \major a8 [ \change Staff="1" e'8 \change
  Staff="2" a,8 \change Staff="1" e'8 ] c'8 [ e,8 \change Staff="2" a,8 \change
  Staff="1" b'8 ] }


% The score definition
\score {
  <<
    \new PianoStaff = "P1" <<
      \context Staff = "1" <<
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOneS" {
          \PartPOneVoiceOneS
        }
      >>
      \context Staff = "2" <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceTwo" {
          \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
